package muscleviewer

// figureView is one side of the flat body figure, generated by
// scripts/bodymap into figure_gen.go from the same meshes as body-map.glb, so
// a muscle's outline here is its mesh on the 3D figure, seen flat.
type figureView struct {
	ViewBox    string
	Silhouette string // the whole body, drawn first as its dark inside
	Regions    []figureRegion
}

// figureRegion is one muscle's outline, as SVG path data (evenodd).
type figureRegion struct {
	Region string
	D      string
}
